ga0c(){return"\u0905\u0928\u0941\u092e\u094b\u0926\u093f\u0924 \u0938\u0939\u093e\u092f\u0915"},
gB5(){return"\u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940"},
ga0_(){return"\u0915\u094b\u0908 \u0915\u094d\u0932\u093f\u0928\u093f\u0915\u0932 \u092a\u0939\u0941\u0902\u091a \u0928\u0939\u0940\u0902: \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u093e \u0907\u0924\u093f\u0939\u093e\u0938, \u0905\u0938\u094d\u092a\u0924\u093e\u0932 \u092f\u093e \u0921\u093e\u092f\u0930\u0940 \u0928\u0939\u0940\u0902 \u0926\u0947\u0916 \u0938\u0915\u0924\u093e\u0964"},
gG3(){return"\u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u093e \u0938\u0939\u093e\u092f\u0915"},
gUC(){return"\u0907\u0924\u093f\u0939\u093e\u0938 \u0926\u0947\u0916 \u0938\u0915\u0924\u093e \u0939\u0948 \u0914\u0930 \u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915 \u0915\u0940 \u0938\u094d\u0935\u0940\u0915\u0943\u0924\u093f \u0915\u0947 \u0924\u0939\u0924 \u092c\u0928\u093e \u0938\u0915\u0924\u093e \u0939\u0948"},
gBu(){return"\u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e \u092e\u0947\u0902"},
